{
  "interface": {
    "mode": "stdin_stdout",
    "signature": "stdin -> stdout"
  },
  "preconditions": [
    {
      "id": "P1",
      "expression": "1 <= n <= 2 * 10^5",
      "description": "The number of intersections is between 1 and 2 * 10^5, inclusive."
    },
    {
      "id": "P2",
      "expression": "1 <= m <= 2 * 10^5",
      "description": "The number of roads is between 1 and 2 * 10^5, inclusive."
    },
    {
      "id": "P3",
      "expression": "Each pair of intersections is connected by no more than one road.",
      "description": "There is at most one road between any two intersections."
    },
    {
      "id": "P4",
      "expression": "No road connects the intersection to itself.",
      "description": "No road has both ends at the same intersection."
    }
  ],
  "postconditions": [
    {
      "id": "Q1",
      "expression": "output == 'YES' or output == 'NO'",
      "description": "The output is either 'YES' or 'NO'."
    },
    {
      "id": "Q2",
      "expression": "output == 'YES' ==> (next(output) == '3' and next(output) == 'l1 p1 ... pl1' and next(output) == 'l2 p1 ... pl2' and next(output) == 'l3 p1 ... pl3')",
      "description": "If the output is 'YES', then it is followed by three lines with the descriptions of the three routes."
    },
    {
      "id": "Q3",
      "expression": "output == 'NO' ==> True",
      "description": "If the output is 'NO', then there are no further lines of output."
    }
  ],
  "invariants": [
    {
      "id": "I1",
      "expression": "all(1 <= pi <= n for pi in p1 ... pl1) and all(1 <= pi <= n for pi in p1 ... pl2) and all(1 <= pi <= n for pi in p1 ... pl3)",
      "description": "The route descriptions contain only valid intersection numbers."
    },
    {
      "id": "I2",
      "expression": "all(1 < pi <= n for pi in p1 ... pl1) and all(1 < pi <= n for pi in p1 ... pl2) and all(1 < pi <= n for pi in p1 ... pl3)",
      "description": "The start and finish intersections of each route are distinct and not the same as any other route's start or finish."
    },
    {
      "id": "I3",
      "expression": "all(pi != pj for pi in p1 ... pl1 for pj in p1 ... pl2) and all(pi != pj for pi in p1 ... pl1 for pj in p1 ... pl3) and all(pi != pj for pi in p1 ... pl2 for pj in p1 ... pl3)",
      "description": "No two routes share any junctions except the start and finish."
    },
    {
      "id": "I4",
      "expression": "all(pi != pj for pi in range(1, n+1) for pj in range(1, n+1) if pi != pj and (pi, pj) in roads and (pj, pi) in roads)",
      "description": "No route visits the same road more than once."
    },
    {
      "id": "I5",
      "expression": "all(pi != pj for pi in range(1, n+1) for pj in range(1, n+1) if pi != pj and (pi, pj) in roads and (pj, pi) in roads)",
      "description": "No route visits the same intersection more than twice."
    }
  ]
}
